// ── 2.3 Composite Pattern ───────────────────────────────────────────────────
public interface IFileSystemComponent { int GetSize(); }
public class FileLeaf(int size) : IFileSystemComponent { public int GetSize() => size; }
public class DirectoryComposite : IFileSystemComponent
{
    private readonly List<IFileSystemComponent> _children = [];
    public void AddChild(IFileSystemComponent c) => _children.Add(c);
    public void RemoveChild(IFileSystemComponent c) => _children.Remove(c);
    public int GetSize()
    {
        int total = 0;
        foreach (var c in _children) total += c.GetSize();
        return total;
    }
}

