// ── 3.5 Mediator Pattern ────────────────────────────────────────────────────
public class AppEventMediator
{
    private readonly Dictionary<string, List<Action<object>>> _listeners = [];
    public void Subscribe(string ev, Action<object> act)
    {
        if (!_listeners.ContainsKey(ev)) _listeners[ev] = [];
        _listeners[ev].Add(act);
    }
    public void Publish(string ev, object data)
    {
        if (_listeners.TryGetValue(ev, out var list))
            foreach (var a in list) a(data);
    }
}

